# Build replacement editable letters with no template instructions in the letters.
def letter(name,title,pars):
 d=Document();sec=d.sections[0];sec.top_margin=Inches(.9);sec.bottom_margin=Inches(.8)
 normal=d.styles['Normal'];normal.font.name='Calibri';normal.font.size=Pt(10.5)
 d.add_heading(title,0)
 for p in pars:d.add_paragraph(p)
 d.save(R/name)
